const b = $json.body ?? $json;

const clean = (v) => v === undefined || v === null ? '' : String(v).trim();

const payload = {
  client_name: clean(b.client_name || b.clientName || b.name),
  company_name: clean(b.company_name || b.companyName || b.company),
  client_email: clean(b.client_email || b.clientEmail || b.email),
  service: clean(b.service || b.offer || b.product),
  requirements: clean(b.requirements || b.project_requirements || b.problem || b.description),
  deliverables: clean(b.deliverables || b.scope),
  timeline: clean(b.timeline || b.delivery_time),
  price: clean(b.price || b.budget || b.amount),
  currency: clean(b.currency || 'USD'),
  payment_terms: clean(b.payment_terms || b.paymentTerms),
  support_terms: clean(b.support_terms || b.supportTerms),
  validity: clean(b.validity || b.proposal_validity),
  seller_name: clean(b.seller_name || b.sellerName || 'WebDecoders'),
  telegram_chat_id: clean(b.telegram_chat_id || b.telegramChatId || b.chat_id)
};

const errors = [];
if (!payload.client_name) errors.push('client_name is required');
if (!payload.service) errors.push('service is required');
if (!payload.requirements) errors.push('requirements are required');
if (!payload.price) errors.push('price is required');
if (!payload.timeline) errors.push('timeline is required');
if (!payload.telegram_chat_id) errors.push('telegram_chat_id is required');

if (payload.client_email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(payload.client_email)) {
  errors.push('client_email is invalid');
}

return [{json:{...payload, valid: errors.length === 0, errors}}];

