const raw = $json;
let proposal = '';

if (raw.message?.content) proposal = raw.message.content;
else if (typeof raw.content === 'string') proposal = raw.content;
else if (typeof raw.text === 'string') proposal = raw.text;
else if (Array.isArray(raw) && raw[0]?.message?.content) proposal = raw[0].message.content;

proposal = String(proposal || '').trim();

if (!proposal) {
  throw new Error('OpenAI returned no proposal text');
}

return [{
  json: {
    proposal,
    document_title: `Sales Proposal - ${$('Normalize Lead Data').item.json.client_name}${$('Normalize Lead Data').item.json.company_name ? ' - ' + $('Normalize Lead Data').item.json.company_name : ''}`
  }
}];

const docId =
  $json.documentId ||
  $json.id ||
  $json.document?.documentId ||
  $('Google Docs - Create Proposal').item.json.documentId ||
  $('Google Docs - Create Proposal').item.json.id ||
  $('Google Docs - Create Proposal').item.json.document?.documentId ||
  '';

if (!docId) throw new Error('Google Docs document ID missing');

return [{
  json: {
    document_id: docId,
    proposal_url: `https://docs.google.com/document/d/${docId}/edit`,
    telegram_message:
      `Proposal ready for ${$('Normalize Lead Data').item.json.client_name}` +
      `${$('Normalize Lead Data').item.json.company_name ? ' (' + $('Normalize Lead Data').item.json.company_name + ')' : ''}` +
      `\n\n${`https://docs.google.com/document/d/${docId}/edit`}`
  }
}];
